  ],
  declarations: [
    MatLegacyTabGroup,
    MatLegacyTabLabel,
    MatLegacyTab,
    MatLegacyInkBar,
    MatLegacyTabLabelWrapper,
    MatLegacyTabNav,
    MatLegacyTabNavPanel,
